:1320px}.compare th,.compare td{padding:14px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);vertical-align:top;text-align:left}.compare th{position:sticky;top:0;background:#fff3ef;color:#7f3c50;font-size:11px;text-transform:uppercase;letter-spacing:.05em}.compare td:first-child{font-weight:800;min-width:170px;background:#fffbfa}.compare .harm{background:#fff7f4}.compare .ilmb{background:#fffaf4}.compare small{display:block;color:var(--muted);margin-top:4px}.note{margin-top:12px;padding:13px 15px;border-left:4px solid var(--rose);background:var(--blush);border-radius:10px}.timeline{display:grid;gap:10px;margin-top:14px}.event{display:grid;grid-template-columns:145px 1fr 1fr;gap:14px;padding:15px;border:1px solid var(--line);border-radius:14px}.event b{color:var(--rose)}.event p{margin:4px 0;color:var(--muted)}.steps{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:14px}.step{padding:16px;border:1px solid var(--line);border-radius:14px;background:#fff}.step b{color:var(--rose)}.flow{display:flex;flex-wrap:wrap;gap:7px;align-items:center;margin-top:10px}.node{padding:7px 9px;border:1px solid var(--line);border-radius:9px;background:#fff}.arr{color:var(--rose);font-weight:800}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.metric{padding:14px;border:1px solid var(--line);border-radius:14px}.metric strong{font-size:21px}.metric small{display:block;color:var(--muted)}.identity{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.identity span{padding:8px 10px;border:1px solid var(--line);border-radius:999px;background:#fff3ef;font-size:12px}.good{background:var(--good)}.warn{background:var(--warn)}.risk{background:var(--risk)}@media(max-width:900px){.quick,.metrics,.steps{grid-template-columns:1fr 1fr}.event{grid-template-columns:1fr}.top{flex-direction:column}.compare{min-width:1180px}}@media(max-width:600px){.shell{padding:14px 10px 50px}.hero{padding:19px}.quick,.metrics,.steps{grid-templat